    unsigned char cmd_mode;
    unsigned char point_num;
    float start_angle;
    float end_angle;
    uint16_t timestamp;
    unsigned short crc_value;
} parsed_data_st;

typedef struct
{
    point_data_t data[POINT_CIRCLE_MAX_SIZE + 1];
    unsigned short vailtidy_point_num;
    double speed;
} full_scan_data_st;

typedef struct
{
    point_data_t data[POINT_PKG_MAX_SIZE + 1];
    unsigned short vailtidy_point_num;
    double speed;
} one_scan_data_st;

#ifdef __cplusplus
}
